            out += `• Kepatuhan Cadangan Deorbiting 25 Tahun (ISO 24113): ${evalRes.data.iso_24113_deorbit_compliant ? 'TERPENUHI (Delta-V Cukup)' : 'KRITIS'}\n\n`;
            out += `PERENCANAAN MANUVER PENGHINDARAN (COLLISION AVOIDANCE MANEUVER - CAM):\n`;
